function layout(){for(const sh of $$('.shell')){if(sh.classList.contains('bd-launch-shell-grid'))continue;const kids=Array.from(sh.children).filter(x=>x.nodeType===1);if(kids.length<3)continue;let center=kids.find(x=>x.matches('main.center,.center,.profile-center,main.main,.main'));if(!center)continue;const ci=kids.indexOf(center);const left=kids.slice(0,ci).reverse().find(x=>x.matches('aside,.side,.rail,.sidebar'))||kids[0];const right=kids.slice(ci+1).find(x=>x.matches('aside,.side,.rail,.sidebar'))||kids[kids.length-1];if(!left||!right||left===center||right===center)continue;sh.classList.add('bd-launch-shell-grid');left.classList.add('bd-launch-left');center.classList.add('bd-launch-center');right.classList.add('bd-launch-right')}}
function postBody(card){return card.querySelector('.post-body,.prolap-text,.post-text,[data-post-body]')}
