function modernCommentButton(card){const cand=card.querySelector('[data-action="bd-comment-v814"],[data-bd-comment-toggle],[data-comment-toggle],[data-comment],button[data-action="comment"],.post-action:nth-child(2),.action-btn[data-comment]');if(!cand||cand.dataset.bdLaunchCommentIcon)return;cand.dataset.bdLaunchCommentIcon='1';cand.classList.add('bd-launch-comment-btn');const txt=(cand.textContent||'').replace(/[◯◌○●□▢]/g,'').trim()||'মন্তব্য';cand.innerHTML=svgComment()+'<span>'+esc(txt)+'</span>'}
