function enhanceCard(card){if(!card||card.nodeType!==1)return;const id=pid(card);if(!id&&!(card.querySelector('.post-body,.prolap-text')&&card.querySelector('.post-actions,.actions')))return;card.classList.add('bd-launch-card');if(id){card.dataset.bdCanonicalPostId=id;card.dataset.postId=card.dataset.postId||id}ensureExpand(card);modernCommentButton(card);card.querySelectorAll('video').forEach(v=>enhanceVideo(card,v));card.querySelectorAll('img').forEach(img=>{if(!img.hasAttribute('loading')&&!img.closest('.avatar,.author-avatar,.post-avatar,.profile-avatar'))img.loading='lazy';if(!img.hasAttribute('decoding'))img.decoding='async'})}
