function clearLoveVisual(card){const b=currentReactionButton(card);if(!b)return;b.classList.remove('active','bd-launch-loved');delete b.dataset.bdLaunchReaction;const lbl=b.querySelector('.bd-react-label,.bd31-react-label,[data-reaction-label]');if(lbl)lbl.textContent='রিয়্যাক্ট';const sym=b.querySelector('.bd-react-symbol,.action-icon,.bd31-react-symbol');if(sym&&!sym.querySelector('img'))sym.textContent='♡'}
async function socialRows(id){const c=client();if(!c)return[];try{const r=await c.rpc('get_post_social',{target_post:String(id)});if(!r.error){const d=Array.isArray(r.data)?r.data[0]:r.data;if(Array.isArray(d?.reactions))return d.reactions}}catch(_){ }for(const t of ['post_reactions','reactions'])try{const r=await c.from(t).select('user_id,reaction').eq('post_id',id).limit(500);if(!r.error)return r.data||[]}catch(_){ }return[]}
async function forceLove(card){const id=pid(card);if(!id)return;return stable(card,async()=>{const s=await session();if(!s?.user){location.href='login.html?next='+encodeURIComponent(location.href);return}setLoveVisual(card);const c=client(),uid=s.user.id;if(c){let done=false;for(const t of ['post_reactions','reactions']){try{const q=await c.from(t).select('reaction').eq('post_id',id).eq('user_id',uid).maybeSingle();if(q.data?.reaction==='love'){done=true;break}if(q.data){const r=await c.from(t).update({reaction:'love'}).eq('post_id',id).eq('user_id',uid);if(!r.error){done=true;break}}else if(!q.error||q.error?.code==='PGRST116'){const r=await c.from(t).insert({post_id:id,user_id:uid,reaction:'love'});if(!r.error){done=true;break}}}catch(_){}}if(!done){try{const rows=await socialRows(id),mine=rows.find(x=>String(x.user_id)===String(uid));if(mine?.reaction!=='love')await c.rpc('toggle_post_reaction',{target_post:String(id),chosen_reaction:'love'})}catch(_){}}}else{try{let a=JSON.parse(localStorage.getItem('bd-master-reactions')||'[]');a=a.filter(x=>!(String(x.post_id)===id&&String(x.user_id)===String(uid)));a.push({post_id:id,user_id:uid,reaction:'love',created_at:new Date().toISOString()});localStorage.setItem('bd-master-reactions',JSON.stringify(a))}catch(_){}}pulseHeart(card);D.dispatchEvent(new CustomEvent('bd:launch-reaction',{detail:{postId:id,reaction:'love'}}));toast('ভালোবাসা দেওয়া হয়েছে')})}
async function toggleLove(card){const id=pid(card);if(!id)return;return stable(card,async()=>{const s=await session();if(!s?.user){location.href='login.html?next='+encodeURIComponent(location.href);return}const c=client(),uid=s.user.id;let mine=null;if(c){try{const rows=await socialRows(id);mine=rows.find(x=>String(x.user_id)===String(uid))||null}catch(_){}if(mine?.reaction==='love'){let done=false;for(const t of ['post_reactions','reactions']){try{const r=await c.from(t).delete().eq('post_id',id).eq('user_id',uid);if(!r.error){done=true;break}}catch(_){}}if(!done){try{await c.rpc('toggle_post_reaction',{target_post:String(id),chosen_reaction:'love'})}catch(_){}}clearLoveVisual(card);D.dispatchEvent(new CustomEvent('bd:launch-reaction',{detail:{postId:id,reaction:null}}));return}return forceLove(card)}try{let a=JSON.parse(localStorage.getItem('bd-master-reactions')||'[]');const i=a.findIndex(x=>String(x.post_id)===id&&String(x.user_id)===String(uid)&&x.reaction==='love');if(i>=0){a.splice(i,1);clearLoveVisual(card)}else{a=a.filter(x=>!(String(x.post_id)===id&&String(x.user_id)===String(uid)));a.push({post_id:id,user_id:uid,reaction:'love',created_at:new Date().toISOString()});setLoveVisual(card)}localStorage.setItem('bd-master-reactions',JSON.stringify(a))}catch(_){}})}
function pulseHeart(card){const host=card.querySelector('.bd-launch-video-host,.post-media,.media')||card;let h=host.querySelector('.bd-launch-reel-heart');if(!h){h=D.createElement('span');h.className='bd-launch-reel-heart';h.textContent='❤️';host.appendChild(h)}h.classList.remove('show');void h.offsetWidth;h.classList.add('show')}
function toggleComments(card){const b=card.querySelector('[data-action="bd-comment-v814"],[data-bd-comment-toggle],[data-comment-toggle],[data-comment],button[data-action="comment"]');if(b){const top=card.getBoundingClientRect().top;b.click();requestAnimationFrame(()=>{const d=card.getBoundingClientRect().top-top;if(Math.abs(d)>1)W.scrollBy(0,d)});return}const p=card.querySelector('.bd31-comment-panel,.bd-fb-comments,.comments,.comment-box');if(!p)return;p.hidden=false;p.classList.toggle('open')}
