function doubleTap(e){const card=cardOf(e.target);if(!card)return;if(e.target.closest('button,a,input,textarea,select,label,[contenteditable="true"]')&&!e.target.closest('video'))return;const now=Date.now(),x=e.clientX??0,y=e.clientY??0,old=tapState.get(card);tapState.set(card,{t:now,x,y});if(old&&now-old.t<330&&Math.hypot(x-old.x,y-old.y)<32){tapState.delete(card);if(e.cancelable)e.preventDefault();forceLove(card)}}
